"""Build the shoreline qualification report without changing UK inputs or scores."""
from pathlib import Path
import csv,html,json,hashlib,shutil
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path(__file__).resolve().parents[3];O=R/'results/uk_2d/g2-partial-wet-2026-10-26';W=Path(__file__).parent
read=lambda n:list(csv.DictReader((O/n).open(encoding='utf-8')))
native=read('native.csv');ridge=read('ridge-extended.csv');storage=read('storage.csv');walls=read('walls.csv')
assert len(native)==108 and len(ridge)==24
f=lambda row,key:float(row[key])
assert all(f(r,'max_volume_error_m3')<=2e-11 and f(r,'minimum_depth_m')>=0 and abs(f(r,'final_time_s')-(.5 if r['kind']=='bank_release' else .2))<1e-12 for r in native)
assert all(abs(f(r,'total_volume_error_m3'))<=2e-11 and f(r,'time_s')==.001 for r in ridge)
counts=[]
for kind in ['fully_wet_lake','shoreline_lake','bank_release']:
 for closure,init in [('FLAT','centroid'),('FLAT','clipped'),('VFR','clipped')]:
  subset=[r for r in native if (r['kind'],r['closure'],r['initialization'])==(kind,closure,init)]
  q=max(f(r,'max_momentum_m2ps') for r in subset);head=max(f(r,'final_head_error_m') for r in subset)
  counts.append(dict(kind=kind,closure=closure,initialization=init,cases=len(subset),maximum_speed_mps=max(f(r,'max_wet_speed_mps') for r in subset),maximum_momentum_m2ps=q,maximum_head_error_m=head,stationary_momentum=q<=2e-11 if kind!='bank_release' else None,physical_head=head<=2e-11 if kind!='bank_release' else None))
for r in ridge:
 r['transfer_m3']=f(r,'volume_left_initial_m3')-f(r,'volume_left_final_m3')
 r['gate_pass']=abs(r['transfer_m3'])<=2e-11 if f(r,'eta_left_m')<f(r,'crest_m') else r['transfer_m3']>2e-11
summary=dict(state='COMPLETE',solver_qualification='VFR with FULL_SWE fails geometric dry-crest isolation; not promoted',native_cases=108,ridge_cases=24,geometry_oracle_tests=5,native_numerical_checks='108/108 completed, finite, nonnegative and volume-conserving',native_groups=counts,ridge_passes=sum(r['gate_pass'] for r in ridge),ridge_failures=sum(not r['gate_pass'] for r in ridge),ridge_rows=ridge,maximum_native_volume_error_m3=max(f(r,'max_volume_error_m3') for r in native),canonical_input_unchanged=True,new_Test6_run=False,physical_cause_of_G2='Unresolved')
protected=R/'corpus/uk-ea-2d/uk-ea-2013-t6a/model.inp'
assert hashlib.sha256(protected.read_bytes()).hexdigest()==json.loads((O/'design.json').read_text(encoding='utf-8'))['protected_input_sha256']
assert all(g['stationary_momentum'] and g['physical_head'] for g in counts if g['closure']=='VFR' and g['kind']!='bank_release')
(O/'summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8')
plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'savefig.dpi':160})
fig,axs=plt.subplots(1,2,figsize=(12,4.6),layout='constrained')
colors=['#455a64','#c75146','#007c91']
for (cl,ini),color in zip([('FLAT','centroid'),('FLAT','clipped'),('VFR','clipped')],colors):
 rows=[r for r in native if r['kind']=='shoreline_lake' and r['closure']==cl and r['initialization']==ini and r['order']=='2' and r['angle_deg']=='0']
 axs[0].semilogy([int(r['n']) for r in rows],[max(1e-16,f(r,'max_momentum_m2ps')) for r in rows],'o-',label=cl+' / '+ini,color=color)
axs[0].axhline(2e-11,color='black',ls=':',label='Declared still-water tolerance')
axs[0].set(xlabel='Mesh divisions per side',ylabel='Maximum momentum magnitude (m²/s)',title='Partially wet lake: second order, 0°');axs[0].legend(fontsize=8);axs[0].set_xticks([8,16,32])
labels=[];values=[]
for momentum,face in [('LOCAL_INERTIAL','MEAN'),('LOCAL_INERTIAL','VFR_FACE'),('FULL_SWE','MEAN'),('FULL_SWE','VFR_FACE')]:
 r=next(r for r in ridge if r['momentum']==momentum and r['face_mode']==face and r['order']=='2' and abs(f(r,'eta_left_m')-.12)<1e-10)
 labels.append(('Local inertial' if momentum=='LOCAL_INERTIAL' else 'Full SWE')+'\n'+face);values.append(r['transfer_m3']*1e6)
axs[1].bar(labels,values,color=['#a7b3b8','#007c91','#c75146','#c75146']);axs[1].set(ylabel='Unphysical transfer in 1 ms (mL)',title='Both water surfaces below a 0.155 m ridge');axs[1].tick_params(axis='x',labelsize=8)
for i,v in enumerate(values):axs[1].annotate(f'{v:.4g}',(i,v),xytext=(0,4),textcoords='offset points',ha='center')
axs[1].set_ylim(0,max(values)*1.2)
fig.savefig(O/'native-controls.png');plt.close(fig)
fig,axs=plt.subplots(1,2,figsize=(12,4.5),layout='constrained')
for name,label in [('whole_domain','Whole domain'),('gate_to_building','Gate to building'),('G2_neighborhood','G2 neighborhood')]:
 rows=[r for r in storage if r['region']==name];axs[0].plot([f(r,'time_s') for r in rows],[100*f(r,'planar_minus_solver_m3')/f(r,'solver_wet_volume_m3') for r in rows],'o-',label=label)
axs[0].set(xlabel='Time (s)',ylabel='Storage difference at the same head (%)',title='Completed Test 6A: wet cells only');axs[0].legend()
for name,label in [('all','All walls'),('gate_shoulders','Gate shoulders'),('building','Building')]:
 rows=[r for r in walls if r['region']==name];axs[1].plot([f(r,'time_s') for r in rows],[100*f(r,'exact_minus_midpoint_m4ps2')/max(1e-30,f(r,'physical_pressure_integral_over_rho_m4ps2')) for r in rows],'o-',label=label)
axs[1].set(xlabel='Time (s)',ylabel='Exact edge integral minus midpoint (%)',title='Hydrostatic geometry diagnostic at saved head');axs[1].legend()
fig.savefig(O/'test6-geometry.png');plt.close(fig)

def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
rows20=[r for r in walls if r['time_s']=='20' and r['region'] in ['all','gate_shoulders','building','outer_sides']]
pressuretable=table(['Region at 20 s','Partly wet wall edges','Wetted length (m)','Exact−midpoint (%)'],[(r['region'],r['partially_wet_edges'],f"{f(r,'wetted_length_m'):.4f}",f"{100*f(r,'exact_minus_midpoint_m4ps2')/f(r,'physical_pressure_integral_over_rho_m4ps2'):.4f}") for r in rows20])
ntable=table(['Condition','Storage / initialization','Cases','Maximum |q| (m²/s)','Interpretation'],[(g['kind'],g['closure']+' / '+g['initialization'],g['cases'],f"{g['maximum_momentum_m2ps']:.3g}",'No transient accuracy reference' if g['kind']=='bank_release' else 'Still; physical shoreline volume differs' if g['kind']=='shoreline_lake' and g['initialization']=='centroid' else 'Physical lake preserved' if g['physical_head'] and g['stationary_momentum'] else 'Physical lake not preserved') for g in counts])
body=f'''<h1>Partially wet banks, wall pressure and geometric crest isolation</h1><p class="date">Test 6A follow-up · 26 October 2026 · Completed diagnostic audit</p>
<p class="finding"><strong>The audit identifies a qualification gap, not the cause of G2's mismatch.</strong> Planar cell storage (VFR) preserves the tested partially wet lakes, but the full shallow-water solver passes water over a dry geometric ridge. Its VFR_FACE setting does not change that result. VFR is therefore not promoted as a Test 6 fix.</p>
<h2>What was tested</h2><p>The same immutable corrected engine image used for the latest Test 6A reassessment is linked directly into a native harness. There are 108 lake/release cases: 8, 16 and 32 divisions per side; irregular triangular grids rotated 0° and 64°; first- and second-order reconstruction; default flat storage with centroid initialization, flat storage with geometrically exact water volumes, and VFR with those same exact volumes. The plane rises 0.155 m per 0.34 m, matching the benchmark bank slope. The test footprint is 1 × 0.68 m. It is an independent control, not the laboratory geometry.</p>
<p>The solver uses full SWE, global RK2 selected by Smagorinsky Cs=0, CFL 0.4, dry depth 0.0001 m and maximum step 0.002 s. Bed friction, wall drag and Coriolis are off. Closed lake tests run 0.2 s; a bank release runs 0.5 s. The preregistered lake tolerance is 2×10⁻¹¹ for head and momentum; volume tolerance is 2×10⁻¹¹ m³. There is no analytical accuracy claim for the release. An adaptive 24-case ridge matrix supplies an independent physical blocking condition and an overtopping positive control. Those 1 ms checks use a 0.0001 s maximum timestep and the default requested CFL 0.7 (automatically capped to 0.5 for full SWE); their log records that cap.</p>
<h2>Storage and still-water results</h2><p>The volume oracle clips each triangle at the water surface, triangulates the wet polygon, and integrates linear depth exactly. It is independent of the engine's storage formulas. Five additional Python tests compare analytical storage with independently clipped polygons and edge pressure with Gaussian quadrature.</p>
<p>All 108 runs finish with finite, nonnegative depths and conserved volume; maximum volume error is {summary['maximum_native_volume_error_m3']:.3g} m³. All 36 fully wet lake cases remain still. All 12 VFR shoreline lakes preserve their physical surface and zero momentum. The 12 flat-storage lakes initialized with exact physical volumes produce currents up to 0.03050 m/s. The default centroid-initialized shoreline lakes also remain still, but contain a different water volume: at the coarsest grid, 0.01081677 rather than the planar analytical 0.01096774 m³ (1.38% low). This is a geometry/closure distinction; a well-balanced discrete lake alone does not prove that its shoreline geometry is exact.</p>{ntable}
<img src="native-controls.png" alt="Native still-water momentum and below-crest transfer controls">
<h2>A dry ridge exposes the missing connection</h2><p>Two triangles share an edge whose two endpoints are both 0.155 m high; the outer vertex of each triangle is at zero elevation. All external edges are closed walls. Water surfaces are 0.10 or 0.12 m on the left and 0.02 m on the right. Both are below the complete shared crest, so physical transfer must be zero. Initial volumes are exact clipped volumes, and VFR reconstructs the intended surfaces.</p>
<p>Over 0.001 s, full SWE transfers about 4.823×10⁻⁶ m³ for the 0.10 m head, and 1.095×10⁻⁵ m³ for the 0.12 m head. The result occurs with both reconstruction orders and is unchanged by MEAN versus VFR_FACE. All eight full-SWE below-crest tests fail the 2×10⁻¹¹ m³ isolation tolerance. Local inertial with VFR_FACE blocks all four below-crest cases. Its MEAN option also leaks in the two 0.12 m cases, demonstrating why centroid-bed tests alone are insufficient. All eight 0.20 m overtopping positive controls transfer water, as expected. These controls establish blocking and transfer direction, not accurate overtopping discharge.</p>
<p>Source inspection explains the full-SWE result: its reconstructed face kernel uses an equivalent bed derived from head and mean depth. The full-SWE interior face path does not apply the endpoint-based VFR_FACE gate. For a partially wet cell, equivalent bed and the actual shared edge crest can differ substantially. The existing VFR_FACE implementation covers the local-inertial path; enabling it is not an implementation of integrated full-SWE shoreline flux.</p>
<h2>Wetted wall width and pressure</h2><p>For an edge of length L with linear bed z(s), wetted width is ∫1[η&gt;z(s)] ds, and hydrostatic force divided by density is (g/2)∫max(η−z(s),0)² ds. For a partially wet edge rising by Δz, these are L(η−z_low)/Δz and gL(η−z_low)³/(6Δz). For a fully wet sloping edge, midpoint pressure underestimates the exact integral by gL(Δz)²/24. A midpoint may even be dry while part of the edge is wet.</p>
<p>These identities do <em>not</em> justify replacing only the wall pressure term: the existing kernel couples pressure to a discrete bed-source correction. Changing one term alone can destroy the still-water balance. A qualified correction must treat storage, wetted face flux, wall pressure and bed source consistently.</p>
<h2>How large is the geometric difference in the completed Test 6A?</h2><p>Diagnostics use the finalized 120-second corrected result, with no new Test 6 simulation. Only cells with mean depth greater than the declared 0.0001 m dry threshold contribute; dry-cell head is not interpreted as a physical water surface. At 20 s, 2,050 such cells intersect their planar bed. Evaluating exact planar storage at their saved heads adds 0.0134907 m³, or 0.0812% of wet-cell stored volume. In the G2 neighborhood (2≤x≤3.3 m, full width), the difference is 0.000410419 m³, or 0.1617%. These are geometry changes at fixed head, not mass-conservation errors. The early differences are larger: among the sampled times, G2-neighborhood storage differs by as much as 3.139% at 1 s, and gate-shoulder pressure quadrature by 7.178% initially. The figures retain the full sampled duration; the 20-second summary is not an upper bound.</p>
{pressuretable}<p>The building's 64 wall edges have constant bed elevation and no partially wet edge at 20 s. The gate shoulders have two partially wet wall edges. The reported pressure percentages compare the exact linear-bed hydrostatic integral with a midpoint evaluation at each saved cell head. They are scalar sums, not net forces and not the solver's reconstructed wall/bed momentum ledger. The all-wall difference is about 0.0620%; gate shoulders about 0.5676%. Small aggregate differences do not rule out local front sensitivity, but this audit does not show a missing building-wall pressure effect that explains G2.</p>
<img src="test6-geometry.png" alt="Storage and wall pressure quadrature differences over the completed Test 6A duration">
<h2>Decision and next implementation gate</h2><p>No physics coefficient, canonical deck, regression anchor or engine default is changed. No new measured-data score is claimed; the <a href="../g2-reconstruction/report.html">previous full comparison and UK reporting panels</a> remain the current result. There is no direct comparison with other hydraulic models.</p>
<ol><li>Develop a consistent full-SWE planar-bed treatment that couples volume/head closure to wet portions of interior and wall faces and a compatible bed source. Retain the current path for its qualified flat-bed regime.</li><li>Require zero below-crest transfer, correct overtopping behavior, fully and partially wet lake balance, positivity, conservation, the existing 12 reconstruction tests and 16 analytical controls before accepting a candidate. Add transient reference cases; the present release checks are stability checks only.</li><li>Then repeat corrected-operator jump-normal and momentum/energy diagnostics and a declared Test 6A comparison. Preserve initial-condition semantics explicitly: matching mean depth, water level and volume simultaneously is generally impossible when changing the storage representation.</li></ol>
<h2>Reproduction and evidence</h2><p><a href="design.json">Declared design and adaptive extension</a> · <a href="summary.json">Machine-readable outcomes, including failures</a> · <a href="execution.json">Executable and source identities</a> · <a href="native.csv">108 native cases</a> · <a href="ridge-extended.csv">24 ridge cases</a> · <a href="storage.csv">Storage by region/time</a> · <a href="walls.csv">Wall integrals by region/time</a> · <a href="geometry-scope.json">Geometry diagnostic scope</a> · <a href="oracle-tests.log">Five independent oracle tests</a></p>
<p>The source directory contains <a href="source/partial_wet_audit.cpp">the native harness</a>, <a href="source/CMakeLists.txt">its build definition</a>, <a href="source/run.py">the explicit source/library runner</a>, <a href="source/geometry.py">geometry diagnostics</a>, <a href="source/test_geometry.py">oracle checks</a> and <a href="source/report.py">report generation</a>. Run the native runner with --source, --library and --output pointing to an ABI-compatible engine source tree, the intended engine library and a reviewable output directory. The recorded result uses the frozen corrected image, not the concurrently edited working checkout. The known unrelated porewater failure from the earlier qualification remains; this audit makes no new full-suite pass claim.</p>'''
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Partially wet bank and wall audit — HydroCouple</title><style>body{max-width:1100px;margin:48px auto;padding:0 24px;font:17px/1.6 system-ui;color:#193042;background:#fafcfd}h1{font-size:2.1em;line-height:1.15}h2{margin-top:2em;color:#075969}.date{color:#526a77}.finding{background:#e5f1f4;padding:20px;border-left:5px solid #007c91}table{width:100%;border-collapse:collapse;font-size:14px}th,td{border-bottom:1px solid #cbd8df;text-align:left;padding:10px}th{background:#edf3f6}img{width:100%;height:auto;margin:20px 0}a{color:#006b86}</style><main>'''+body+'</main></html>'
(O/'report.html').write_text(page,encoding='utf-8')
source=O/'source';source.mkdir(exist_ok=True)
for p in W.iterdir():
 if p.suffix in ['.cpp','.py','.txt']:shutil.copy2(p,source/p.name)
files=['report.html','summary.json','design.json','execution.json','native.csv','ridge-extended.csv','storage.csv','walls.csv','geometry-scope.json','oracle-tests.log','native.log','ridge-extended.log','native-controls.png','test6-geometry.png']+[str(p.relative_to(O)) for p in source.iterdir() if p.is_file()]
manifest=dict(state='COMPLETE',qualification='diagnostic failures retained; no solver promotion',files={n:hashlib.sha256((O/n).read_bytes()).hexdigest() for n in files})
(O/'publication-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')
print(json.dumps({k:summary[k] for k in ['state','solver_qualification','native_cases','ridge_cases','ridge_passes','ridge_failures']},indent=2))
